UPDATE `node` SET `ownerId` = ? WHERE `node`.`id` IN (SELECT * FROM (SELECT `q0`.`id` FROM `node` AS `q0` WHERE ((`q0`.`ownerId` = ? AND BINARY `q0`.`ownerId` = ?) AND TRUE) GROUP BY `q0`.`id` HAVING MIN((SELECT CASE WHEN (`q1`.`ownerId` = ? AND BINARY `q1`.`ownerId` = ?) THEN 1 ELSE JSON_EXTRACT('{}', '__viborm_refused__') END AS `__viborm_judged__` FROM (SELECT `q2`.`id`, `q2`.`ownerId`, `q2`.`tags`, `q2`.`parentId` FROM `node` AS `q2` WHERE FALSE UNION ALL SELECT `q0`.`id`, ?, `q0`.`tags`, `q0`.`parentId`) AS `q1`)) = 1 ORDER BY `q0`.`id` ASC LIMIT 2) AS `q3`);
-- ["u2","u1","u1","u2","u2","u2"]
